/**
 * UI反馈工具类 - 基于Element Plus Message组件封装
 * 参考文档: https://element-plus.org/zh-CN/component/message.html
 */

import { ElMessage, ElMessageBox, ElNotification, ElLoading } from 'element-plus';

/**
 * 通用消息提示函数
 * @param {string|Object} options - 消息配置选项，可以是字符串或配置对象
 * @param {string} [options.message=''] - 消息文字内容
 * @param {'primary'|'success'|'warning'|'info'|'error'} [options.type='info'] - 消息类型
 * @param {boolean} [options.plain=false] - 是否为纯色背景 (v2.6.3+)
 * @param {string|Component} [options.icon] - 自定义图标，会覆盖type的默认图标
 * @param {boolean} [options.dangerouslyUseHTMLString=false] - 是否将message作为HTML片段处理
 * @param {string} [options.customClass=''] - 自定义CSS类名
 * @param {number} [options.duration=3000] - 显示时间(毫秒)，设为0则不自动关闭
 * @param {boolean} [options.showClose=false] - 是否显示关闭按钮
 * @param {Function} [options.onClose] - 关闭时的回调函数
 * @param {number} [options.offset=16] - 距离窗口顶部的偏移量
 * @param {string|HTMLElement} [options.appendTo] - 设置message的根元素，默认为document.body
 * @param {boolean} [options.grouping=false] - 是否合并内容相同的消息
 * @returns {Object} Message实例，包含close方法用于手动关闭
 */
export const showMessageBase = (options) => {
    // 如果传入的是字符串，转换为配置对象
    if (typeof options === 'string') {
        options = { message: options };
    }
    
    return ElMessage(options);
};

/**
 * 显示成功消息
 * @param {string|Object} options - 消息内容或配置对象
 * @param {string} [options.message] - 消息文字内容
 * @param {number} [options.duration=3000] - 显示时间(毫秒)
 * @param {boolean} [options.showClose=false] - 是否显示关闭按钮
 */
export const showMessageSuccess = (options) => {
    if (typeof options === 'string') {
        return showMessageBase({
            type: 'success',
            message: options
        });
    }
    
    return showMessageBase({
        type: 'success',
        ...options
    }); 
};

