// ===================== MessageBox 消息弹框封装 =====================

/**
 * 通用消息弹框函数
 * @param {string|Object} options - 弹框配置选项，可以是字符串或配置对象
 * @param {string} [options.title=''] - 弹框标题
 * @param {string|VNode|Function} [options.message=''] - 弹框内容
 * @param {'primary'|'success'|'warning'|'info'|'error'} [options.type=''] - 消息类型
 * @param {string|Component} [options.icon] - 自定义图标，会覆盖type的默认图标
 * @param {boolean} [options.dangerouslyUseHTMLString=false] - 是否将message作为HTML片段处理
 * @param {string} [options.customClass=''] - 自定义CSS类名
 * @param {CSSProperties} [options.customStyle={}] - 自定义内联样式
 * @param {string} [options.modalClass] - 遮罩的自定义类名
 * @param {boolean} [options.showClose=true] - 是否显示右上角关闭按钮
 * @param {Function} [options.beforeClose] - messageBox关闭前的回调，会暂停消息弹出框的关闭过程
 * @param {boolean} [options.distinguishCancelAndClose=false] - 是否将取消（点击取消按钮）与关闭（点击关闭按钮或遮罩层、按下Esc键）进行区分
 * @param {boolean} [options.lockScroll=true] - 是否在MessageBox出现时将body滚动锁定
 * @param {boolean} [options.showCancelButton=false] - 是否显示取消按钮
 * @param {boolean} [options.showConfirmButton=true] - 是否显示确定按钮
 * @param {string} [options.cancelButtonText='Cancel'] - 取消按钮的文本内容
 * @param {string} [options.confirmButtonText='OK'] - 确定按钮的文本内容
 * @param {string} [options.cancelButtonClass=''] - 取消按钮的自定义类名
 * @param {string} [options.confirmButtonClass=''] - 确定按钮的自定义类名
 * @param {boolean} [options.closeOnClickModal=true] - 是否可通过点击遮罩层关闭MessageBox
 * @param {boolean} [options.closeOnPressEscape=true] - 是否可通过按下ESC键关闭MessageBox
 * @param {boolean} [options.closeOnHashChange=true] - 是否在hash改变时关闭MessageBox !!!
 * @param {boolean} [options.center=false] - 是否居中布局
 * @param {boolean} [options.draggable=false] - MessageBox是否可拖放
 * @param {boolean} [options.overflow=false] - MessageBox拖动范围可以超出可视区
 * @param {boolean} [options.roundButton=false] - 是否使用圆角按钮
 * @param {string} [options.buttonSize='default'] - 自定义确认按钮及取消按钮的大小
 * @returns {Promise} Promise对象，用于处理用户操作结果
 */
export const showMessageBox = (options) => {
    // 如果传入的是字符串，转换为配置对象
    if (typeof options === 'string') {
        options = { message: options };
    }
    
    return ElMessageBox(options);
};

/**
 * 显示警告提示弹框 (Alert)
 * @param {string} message - 消息内容
 * @param {string} [title=''] - 弹框标题
 * @param {Object} [options={}] - 其他配置选项
 * @returns {Promise} Promise对象
 */
export const showMessageBoxAlert = (message, title = '', options = {}) => {
    return ElMessageBox.alert(message, title, {
        confirmButtonText: 'OK',
        ...options
    });
};

/**
 * 显示确认弹框 (Confirm)
 * @param {string} message - 消息内容
 * @param {string} [title='Warning'] - 弹框标题
 * @param {Object} [options={}] - 其他配置选项
 * @returns {Promise} Promise对象
 */
export const showMessageBoxConfirm = (message, title = 'Warning', options = {}) => {
    return ElMessageBox.confirm(message, title, {
        confirmButtonText: 'OK',
        cancelButtonText: 'Cancel',
        type: 'warning',
        ...options
    });
};

/**
 * 显示输入提示弹框 (Prompt)
 * @param {string} message - 消息内容
 * @param {string} [title='Tip'] - 弹框标题
 * @param {Object} [options={}] - 其他配置选项
 * @param {RegExp} [options.inputPattern] - 输入框的校验表达式
 * @param {Function} [options.inputValidator] - 输入框的校验函数
 * @param {string} [options.inputErrorMessage] - 校验未通过时的提示文本
 * @param {string} [options.inputPlaceholder] - 输入框占位文本
 * @param {string} [options.inputType='text'] - 输入框的类型
 * @param {string} [options.inputValue=''] - 输入框的初始文本
 * @returns {Promise} Promise对象，成功时返回包含value的对象
 */
export const showMessageBoxPrompt = (message, title = 'Tip', options = {}) => {
    return ElMessageBox.prompt(message, title, {
        confirmButtonText: 'OK',
        cancelButtonText: 'Cancel',
        ...options
    });
};

// ===================== Notification 通知封装 =====================

/**
 * 通用通知函数
 * @param {string|Object} options - 通知配置选项，可以是字符串或配置对象
 * @param {string} [options.title=''] - 通知标题
 * @param {string|VNode|Function} [options.message=''] - 通知内容
 * @param {'primary'|'success'|'warning'|'info'|'error'} [options.type=''] - 通知类型
 * @param {string|Component} [options.icon] - 自定义图标，会覆盖type的默认图标
 * @param {boolean} [options.dangerouslyUseHTMLString=false] - 是否将message作为HTML片段处理
 * @param {string} [options.customClass=''] - 自定义CSS类名
 * @param {number} [options.duration=4500] - 显示时间(毫秒)，设为0则不自动关闭
 * @param {'top-right'|'top-left'|'bottom-right'|'bottom-left'} [options.position='top-right'] - 自定义弹出位置
 * @param {boolean} [options.showClose=true] - 是否显示关闭按钮
 * @param {Function} [options.onClose] - 关闭时的回调函数
 * @param {Function} [options.onClick] - 点击通知时的回调函数
 * @param {number} [options.offset=0] - 距离屏幕边缘的偏移量
 * @param {string|HTMLElement} [options.appendTo] - 设置通知的根元素，默认为document.body
 * @param {number} [options.zIndex=0] - 初始zIndex
 * @param {string|Component} [options.closeIcon='Close'] - 自定义关闭图标
 * @returns {Object} Notification实例，包含close方法用于手动关闭
 */
export const showNotificationBase = (options) => {
    // 如果传入的是字符串，转换为配置对象
    if (typeof options === 'string') {
        options = { message: options };
    }
    
    return ElNotification(options);
};

