<template>
  <div class="mobile-conversation-history" @click="hideContextMenu">
    <!-- 搜索头部组件 -->
    <mobile-conversation-search-header v-model="searchText" @search="handleSearch" @cancel="handleSearchCancel"
      @more="handleMore" />

    <!-- 页面标题 -->
    <div v-if="!searchText" class="mobile-page-title">
      <div class="mobile-page-title-text">{{ t('conversations') }}</div>
      <div class="mobile-new-chat-btn" @click="handleNewChat">
        <div class="def-new-text">{{ t('new') }}</div>
        <mobile-l-img :src="'/static/mobile_images/mobile-new-chat-icon.png'" w="16px" h="16px" />
      </div>
    </div>

    <div v-if="searchResultText" class="mobile-search-result">
      <div>{{ searchResultText }}</div>
    </div>

    <!-- 主内容区域 -->
    <div class="mobile-conversation-content">
      <!-- 未登录状态 -->
      <mobile-empty-state v-if="!isLoggedIn" type="no-login" :title="t('history')"
        :action-text="t('signInToSeeHistory')" @action="handleSignIn" />

      <!-- 加载状态 -->
      <div v-else-if="loading && conversationList.length === 0" class="mobile-loading-container">
        <van-loading type="spinner" size="20px" />
        <span class="loading-text">{{ t('loading') }}</span>
      </div>

      <!-- 错误状态 -->
      <mobile-empty-state v-else-if="errorMessage && !loading" type="error" :error-message="errorMessage"
        :action-text="t('retry')" @action="retryLoad" />

      <!-- 无数据状态 -->
      <mobile-empty-state v-else-if="conversationList.length === 0 && !loading" type="no-data"
        :message="searchText ? t('noResultFound') : t('noConversations')"
        :action-text="!searchText ? t('pullToRefresh') : ''" @action="refreshData" />

      <!-- 对话列表 -->
      <div v-else class="mobile-conversation-list" @scroll="handleScroll">
        <!-- 对话列表项 -->
        <div class="mobile-conversation-items">
          <template v-for="(group, groupIndex) in groupedConversations" :key="groupIndex">
            <!-- 分组标题 -->
            <div v-if="!searchText" class="mobile-time-section" :class="`mobile-section-${group.type || 'default'}`">
              <div class="mobile-time-label">{{ group.label }}</div>
            </div>
            <!-- 对话项 -->
            <mobile-conversation-list-item v-for="conversation in group.conversations" :key="conversation.id"
              :conversation="conversation" :time-label="conversation.time"
              :is-selected="selectedConversations.includes(conversation.id)"
              :is-active="conversation.id === currentConversationId"
              :is-long-pressing="isLongPressingConversation(conversation.id)" @click="handleConversationClick"
              @long-press="handleLongPress" />
          </template>
        </div>

        <!-- 加载更多状态 -->
        <div v-if="loading && conversationList.length > 0" class="mobile-loading-more">
          <van-loading type="spinner" size="20px" />
          <span class="loading-text">{{ t('loading') }}</span>
        </div>

        <!-- 无更多数据 -->
        <div v-if="!hasMore && conversationList.length > 0 && !loading" class="mobile-no-more">
          <span class="no-more-text">{{ t('noMore') }}</span>
        </div>
      </div>
    </div>

    <mobile-rename-dialog 
      v-model:visible="renameDialogVisible"  
      :conversation="selectedActionConversation"
      @onConfirm="handleConfirmRename" 
    /> 

    <!-- 长按上下文菜单 -->
    <mobile-context-menu :visible="contextMenuVisible" :position="contextMenuPosition"
      :conversation="contextMenuConversation" @action="handleContextMenuAction" @hide="hideContextMenu" />

    <!-- 底部区域 -->
    <mobile-bottom-bar @camera-action="handleCameraAction" />
    <mobile-settings-sheet v-model:visible="settingsSheetVisible" />
  </div>
</template>

<script setup>
import { ref, watch, computed, onMounted, onUnmounted } from 'vue';
import { useI18n } from 'vue-i18n';
import { routerToLogin, routerTo } from '@/router/navigation';
import { useConversationData } from '@/composables/useConversationData';
import { useLongPressMenu } from '@/composables/useLongPressMenu';
import { ROUTER_PATHS } from  '@/router/constants';

// 导入组件
import MobileLImg from '@/mobile/components/mobile-l-img.vue';
import MobileConversationSearchHeader from '@/mobile/components/business/mobile-conversation-search-header.vue';
import MobileConversationListItem from '@/mobile/components/business/mobile-conversation-list-item.vue';
import MobileEmptyState from '@/mobile/components/business/mobile-empty-state.vue';
import MobileContextMenu from '@/mobile/components/business/mobile-context-menu.vue';
import MobileBottomBar from '@/mobile/components/business/mobile-bottom-bar.vue';
import MobileRenameDialog from '@/mobile/components/dialog/mobile-rename-dialog.vue';
import MobileSettingsSheet from '@/mobile/components/dialog/mobile-settings-sheet.vue';

// Composables
const { t } = useI18n();
const {
  // 状态
  searchText,
  loading,
  hasMore,
  errorMessage,
  showPreloader,
  isLoggedIn,
  currentConversationId,
  conversationList,
  groupedConversations,
  refreshData,
  retryLoad,
  initializeData,
  setCurrentConversationStatus,
  renameConversation,
  deleteConversations,
  debouncedSearch,
  debouncedLoadMore
} = useConversationData({ enableMobileFeatures: true });

const {
  contextMenuVisible,
  contextMenuPosition,
  contextMenuConversation,
  isScrolling,
  showContextMenu,
  hideContextMenu,
  setLongPressConversation,
  setScrolling,
  isLongPressingConversation
} = useLongPressMenu();

// 本地状态
const selectedConversations = ref([]);
const isSelectionMode = ref(false);
const selectedActionConversation = ref(null);
const renameDialogVisible = ref(false);
const settingsSheetVisible = ref(false);

const searchResultText = computed(() => {
  let count = conversationList.value.length;
  if (count > 0 && searchText.value) {
    return count == 1 ? t('searchResultForText', { count, text: searchText.value }) : t('searchResultsForText', { count, text: searchText.value });
  } else if (count == 0 && searchText.value) {
    return t('noResultForText', { text: searchText.value });
  } else {
    return '';
  }
});

// 事件处理
const handleSearch = (searchValue) => {
  debouncedSearch(searchValue);
};

const handleSearchCancel = () => {
  searchText.value = '';
};

const handleMore = () => {
  routerTo('/');
};

const handleNewChat = () => {
  routerTo('/', {});
};

const handleSignIn = () => {
  routerToLogin();
};

const handleConversationClick = (conversation) => {
  if (contextMenuVisible.value) return;

  if (isSelectionMode.value) {
    toggleSelection(conversation.id);
  } else {
    setCurrentConversationStatus(conversation);
    routerTo(`${ROUTER_PATHS.ALIEN_CHAT}/${conversation.id}`);
  }
};

const handleLongPress = (conversation, position) => {
  if (!isScrolling.value) {
    setLongPressConversation(conversation);
    showContextMenu(conversation, position);
  }
};

const handleScroll = (e) => {
  const el = e.target;
  
  setScrolling(true);
  
  // 预加载逻辑
  const isNearPreload = el.scrollTop + el.clientHeight >= el.scrollHeight - 100;
  showPreloader.value = isNearPreload && hasMore.value && !loading.value && conversationList.value.length > 0;

  // 加载更多逻辑
  const isNearBottom = el.scrollTop + el.clientHeight >= el.scrollHeight - 50;
  if (isNearBottom) {
    debouncedLoadMore();
  }

  // 延迟重置滚动状态
  setTimeout(() => setScrolling(false), 150);
};

const handleContextMenuAction = (action) => {
  if (!contextMenuConversation.value) return;

  switch (action) {
    case 'rename':
      handleRename(contextMenuConversation.value);
      break;
    case 'delete':
      handleDelete(contextMenuConversation.value);
      break;
  }
  hideContextMenu();
};

const handleRename = (conversation) => {
  selectedActionConversation.value = conversation;
  renameDialogVisible.value = true;
};

const handleDelete = (conversation) => {
  selectedConversations.value = [conversation.id];
  showConfirmDialog({
    className: 'mobile-delete-dialog',
    title: t('deleteConversation'),
    message: t('deleteConversationDescription'),
    confirmButtonText: t('delete'),
    cancelButtonText: t('cancel'),
    confirmButtonColor: '#007AFF',
    cancelButtonColor: '#007AFF',
  })
    .then(() => {
      handleConfirmDelete();
    })
    .catch(() => {
      deleteDialogVisible.value = false;
      selectedActionConversation.value = null;
    });
};

const handleConfirmRename = async (newTitle) => {
  const success = await renameConversation(selectedActionConversation.value, newTitle);
  if (success) {
    renameDialogVisible.value = false;
    selectedActionConversation.value = null;
  }
};

const handleConfirmDelete = async () => {
  const success = await deleteConversations(selectedConversations.value);
  if (success) {
    selectedConversations.value = [];
    exitSelectionMode();
  }
};

const handleCameraAction = () => {
  settingsSheetVisible.value = true;
};

// 选择模式相关
const toggleSelection = (conversationId) => {
  const index = selectedConversations.value.indexOf(conversationId);
  if (index > -1) {
    selectedConversations.value.splice(index, 1);
  } else {
    selectedConversations.value.push(conversationId);
  }
};

const exitSelectionMode = () => {
  isSelectionMode.value = false;
  selectedConversations.value = [];
};

// 生命周期
onMounted(() => {
  initializeData();
});

onUnmounted(() => {
  // Composables会自动清理内部的定时器
});

// 监听登录状态变化
watch(() => isLoggedIn.value, (newLoginStatus, oldLoginStatus) => {
  if (newLoginStatus !== oldLoginStatus) {
    if (newLoginStatus) {
      initializeData();
    } else {
      // 清理状态
      selectedConversations.value = [];
      isSelectionMode.value = false;
      renameDialogVisible.value = false;
      selectedActionConversation.value = null;
      hideContextMenu(); 
    }
  }
});
</script>


