<template>
  <van-dialog class-name="mobile-rename-dialog" v-model:show="showDialog" :title="t('renameConversation')"
    :confirm-button-text="t('ok')" :cancel-button-text="t('cancel')" cancel-button-color="#007AFF"
    show-cancel-button @confirm="handleConfirm" @cancel="closeDialog">
    <div class="mobile-rename-dialog-content">
      <van-field ref="inputRef" v-model="newTitle" autofocus @focus="onInputFocus" @blur="onInputBlur" />
    </div>
  </van-dialog>
</template>

<script setup>
// 引入区域
import { ref, computed, watch, nextTick } from 'vue';
import { useI18n } from 'vue-i18n';

// props区域
const props = defineProps({
  visible: {
    type: Boolean,
    default: false
  },
  conversation: {
    type: Object,
    default: null
  }
});

// emits区域
const emit = defineEmits(['update:visible', 'onConfirm']);

// 变量区域
const { t } = useI18n();
const inputRef = ref(null);
const newTitle = ref('');
const showDialog = ref(false);
const isInputFocused = ref(false);

// 计算属性区域
const canConfirm = computed(() => {
  return newTitle.value.trim().length > 0 &&
    newTitle.value.trim() !== props.conversation?.title;
});

// 点击事件区域
const closeDialog = () => {
  emit('update:visible', false);
  newTitle.value = '';
};

const handleConfirm = () => {
  if (!canConfirm.value) return;

  emit('onConfirm', newTitle.value.trim());
  closeDialog();
};

// 自定义事件区域
const onInputFocus = () => {
  isInputFocused.value = true;
};

const onInputBlur = () => {
  isInputFocused.value = false;
};

// 监听visible变化，自动聚焦输入框和设置初始值
watch(() => props.visible, (newVisible) => {
  if (newVisible && props.conversation) {
    newTitle.value = props.conversation.title || '';
    showDialog.value = true;
    nextTick(() => {
      if (inputRef.value) {
        inputRef.value.focus();
      }
    });
  }
});
</script>

