<template>
  <div class="mobile-search-header">
    <div class="mobile-search-container">
      <div class="mobile-search-input">
        <mobile-l-img :src="'/static/mobile_images/search_icon.png'" w="18px" h="18px" class="search-icon" />
        <input type="text" :placeholder="t('searchConversations')" v-model="searchText" class="search-input-field"
          @input="handleInput" />
        <div v-if="searchText.length > 0" @click="clearSearch" class="clear-search-icon">
          <mobile-l-img :src="'/static/mobile_images/mobile-search-clear.png'" w="24px" h="24px" />
        </div>
      </div>
    </div>
    <div v-if="searchText.length > 0" class="mobile-search-cancel" @click="handleCancel">
      {{ t('cancel') }}
    </div>
    <div v-else class="mobile-more-icon" @click="handleMore">
      <mobile-l-img src="/static/mobile_images/more_action_icon.png" w="32px" h="32px" />
    </div>
  </div>
</template>

<script setup>
import { ref, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';
// Props
const props = defineProps({
  modelValue: { type: String, default: '' }
});

// Emits
const emit = defineEmits(['update:modelValue', 'search', 'cancel', 'more']);

// Variables
const { t } = useI18n();
const searchText = ref(props.modelValue);

// Watch
watch(() => props.modelValue, (newVal) => {
  searchText.value = newVal;
});

watch(searchText, (newVal) => {
  emit('update:modelValue', newVal);
});

// Methods
const handleInput = () => {
  emit('search', searchText.value);
};

const clearSearch = () => {
  searchText.value = '';
  emit('search', '');
};

const handleCancel = () => {
  searchText.value = '';
  emit('cancel');
};

const handleMore = () => {
  emit('more');
};
</script>

