<template>
  <div class="mobile-conversation-item" :class="{
    'mobile-item-selected': isSelected,
    'mobile-item-active': isActive,
    'long-pressing': isLongPressing
  }" @click.stop="handleClick" @touchstart="handleTouchStart" @touchmove="handleTouchMove" @touchend="handleTouchEnd"
    @touchcancel="handleTouchCancel" @contextmenu.prevent>
    <div class="mobile-conversation-info">
      <div class="mobile-conversation-title">{{ conversation.title }}</div>
      <div class="mobile-time-group-label">{{ timeLabel }}</div>
    </div>
  </div>
</template>

<script setup>
import { ref } from 'vue';

// Props
const props = defineProps({
  conversation: { type: Object, required: true },
  timeLabel: { type: String, required: true },
  isSelected: { type: Boolean, default: false },
  isActive: { type: Boolean, default: false },
  isLongPressing: { type: Boolean, default: false }
});

// Emits
const emit = defineEmits(['click', 'longPress']);

// 长按相关变量
const longPressTimer = ref(null);
const touchStartPosition = ref({ x: 0, y: 0 });
const LONG_PRESS_DURATION = 600;
const SWIPE_THRESHOLD = 10;

// 事件处理
const handleClick = () => {
  emit('click', props.conversation);
};

const handleTouchStart = (event) => {
  const touch = event.touches[0];
  touchStartPosition.value = {
    x: touch.clientX,
    y: touch.clientY
  };

  longPressTimer.value = setTimeout(() => {
    emit('longPress', props.conversation, {
      x: touch.clientX,
      y: touch.clientY + 60
    });
  }, LONG_PRESS_DURATION);
};

const handleTouchMove = (event) => {
  if (longPressTimer.value && touchStartPosition.value) {
    const touch = event.touches[0];
    const deltaX = Math.abs(touch.clientX - touchStartPosition.value.x);
    const deltaY = Math.abs(touch.clientY - touchStartPosition.value.y);

    if (deltaX > SWIPE_THRESHOLD || deltaY > SWIPE_THRESHOLD) {
      clearTimeout(longPressTimer.value);
      longPressTimer.value = null;
    }
  }
};

const handleTouchEnd = () => {
  if (longPressTimer.value) {
    clearTimeout(longPressTimer.value);
    longPressTimer.value = null;
  }
  touchStartPosition.value = { x: 0, y: 0 };
};

const handleTouchCancel = () => {
  if (longPressTimer.value) {
    clearTimeout(longPressTimer.value);
    longPressTimer.value = null;
  }
  touchStartPosition.value = { x: 0, y: 0 };
};
</script>

